static void gstage_tlb_flush(struct kvm_gstage *gstage, u32 level, gpa_t addr)
{
	unsigned long order = PAGE_SHIFT;
	if (gstage_level_to_page_order(level, &order))
		return;
	addr &= ~(BIT(order) - 1);

while (addr < end) {
	found_leaf = kvm_riscv_gstage_get_leaf(gstage, addr, &ptep, &ptep_level);
	ret = gstage_level_to_page_size(ptep_level, &page_size);
	...
	if (!(addr & (page_size - 1)) && ((end - addr) >= page_size))
		kvm_riscv_gstage_op_pte(gstage, addr, ptep, ptep_level, GSTAGE_OP_WP);
next:
	addr += page_size;

while (addr < end) {
	found_leaf = kvm_riscv_gstage_get_leaf(gstage, addr, &ptep, &ptep_level);
	ret = gstage_level_to_page_size(ptep_level, &page_size);
	...
	if (!(addr & (page_size - 1)) && ((end - addr) >= page_size))
		kvm_riscv_gstage_op_pte(gstage, addr, ptep, ptep_level, GSTAGE_OP_CLEAR);
next:
	addr += page_size;

ret = gstage_level_to_page_size(ptep_level, &page_size);
...
WARN_ON(addr & (page_size - 1));
...
else if (op == GSTAGE_OP_WP)
	set_pte(ptep, __pte(pte_val(ptep_get(ptep)) & ~_PAGE_WRITE));
if (pte_val(*ptep) != pte_val(old_pte))
	gstage_tlb_flush(gstage, ptep_level, addr);

for (i = 0; i < kvm_riscv_gstage_pgd_levels; i++) {
	if (page_size == (psz << (i * kvm_riscv_gstage_index_bits))) {
		*out_level = i;
		return 0;
	}
}
return -EINVAL;
